// === Tab: mySketch.js ===
let theShader;
const particleCount = 600;
const particles = [];
const w = 500;
const h = 500;
let g;
let t = 0;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/1969800/files/vert.glsl', 'frag.glsl');
}

function setup() {
	background(255);

  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  createCanvas(w, h, WEBGL);
	g = createGraphics(w, h);
	g.background(255);
	g.stroke(96 * 1.6, 80 * 1.6, 71 * 1.6, 180);
	g.fill(96, 80, 71, 180);

	for (let i = 0; i < particleCount; i++) { 
    particles.push(new Particle({
      x: Math.random() * w,
      y: Math.random() * h,
      vx: Math.random() * 10 - 5,
      vy: Math.random() * 10 - 5,
      ax: Math.random() * 0.5 - 0.25,
      ay: Math.random() * 0.5 - 0.25,
      jx: Math.random() * 0.05 - 0.025,
      jy: Math.random() * 0.05 - 0.025,
      mass: (Math.random() + 0.5) * .65,
      radius: 1
    }));

    particles[particles.length - 1].radius =
			particles[particles.length - 1].mass * 3 + .1;
  }

	particlesTexture = createImage(w, h);
	setTextureFromParticles(particles);
	theShader.setUniform("u_particles", g);
}

function setTextureFromParticles(particles) {	
	for (let i = 0; i < particleCount; i++) {
		const index = i * 4;
		const p = particles[i];

		g.circle(p.x, p.y, p.radius);
	}
}

function draw() {
	// calculate
	var t = millis();
	particles.map(updateParticle);
  particles.map(applyCanvasConstraints);

  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", t / 1000.0);
  //theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);

	setTextureFromParticles(particles);
	theShader.setUniform("u_particles", g);

	if (t % 3 === 0) {
		g.background(255, 4);
	}
  // rect gives us some geometry on the screen
  rect(0,0,w,h);
}

function updateParticle(particle, index, particles) {
    const cluster = findParticleCluster(
      particle,
      particles, Math.random() * 30 + 40
    );
    applyForces(particle, cluster);
}

function applyCanvasConstraints(particle) {
  if (particle.x < 0) {
    particle.x = particle.radius;
    //particle.vx *= -1;
  } else if (particle.x > w) {
    particle.x = w - particle.radius;
    particle.vx *= -.1
  }

  if (particle.y <= 0) {
    particle.y = particle.radius;
    particle.vy *= -1;
  } else if (particle.y >= h) {
    particle.y = particle.radius;
    particle.vy *= -.1;
		particle.x = Math.random() * w;
  }
}

function applyForces(particle, particleCluster) {

  for (let p of particleCluster) {
    const distX = particle.x - p.x;
    const distY = particle.y - p.y;
    const dist = sqrt(distX*distX + distY*distY);
    const dmx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - particle.x;
    const dmy = h - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - particle.y;
    const dmSquared = dmx*dmx + dmy*dmy; 

    let forceX = -distX * 0.0006;
    let forceY = -distY * 0.0005;

    if (dmSquared <= 80*80 && ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
      forceX -= dmx * 0.004;
      forceY += dmy * 0.001;
    }

    if (dist <= (particle.radius * 0.5) * (p.radius * 1.1)) {
        forceX *= -1;
        forceY *= -1;
        particle.vx *= -.9;
        particle.vy *= -.9;
        particle.jx += forceX * 1;
        particle.jy += forceY * 1;
        p.jx -= forceX * .1;
        p.jy -= forceY * .1;
        particle.ax *= -.9;
        particle.ay *= -.9;
        p.ax *= -.9;
        p.ay *= -.9;
        p.vx *= -.9;
        p.vy *= -.9;
    }

    // Newton's second law of motion
    // Equation: F = ma
    // Solve for a:  a = F / m;
    const accelerationX = (forceX + (Math.random() - 0.5) * 0.15) / particle.mass;
    const accelerationY = (forceY + ((Math.random() - 0.5) * 0.05) + 0.04) / particle.mass;

    // Newton's third law of motion
    // if an object A exerts a force on object B
    // object B also exerts an equal and opposite force on object A
    particle.ax += accelerationX;
    particle.ay += accelerationY;
    p.vx -= accelerationX;
    p.vy -= accelerationY;
  }

  var p = particle;
  p.ax += p.jx;
  p.ay += p.jy;
  p.vx += p.ax;
  p.vy += p.ay;
  p.x += p.vx;
  p.y += p.vy;

  // reset jerk (third derivative of position with respect to time)
  p.jx *= 0.9;
  p.jy *= 0.9;

  p.ax = 0;
  p.ay = 0;

  // damping
  p.vx *= 0.28;
  p.vy *= 0.28;
}

// a particle cluster is a bunch of particles that are neighbouring
// one another within a certain radius
function findParticleCluster(particle, particles, radius = 400) {
  var cluster = [];
  radiusSquared = radius * radius;

  for (let p of particles.filter(p => p !== particle)) {
    var distX = particle.x - p.x;
    var distY = particle.y - p.y;
    const distSquared = distX*distX + distY*distY;

    if (distSquared <= radiusSquared) {
      cluster.push(p);
    }
  }
  return cluster;
}

class Particle {
  constructor ({ x, y, vx, vy, ax, ay, jx, jy, mass = 1, radius = 1}) {
    this.x = x;
    this.y = y;
    this.vx = vx;
    this.vy = vy;
    this.ax = ax;
    this.ay = ay;
    this.jx = jx;
    this.jy = jy;
    this.mass = mass;
    this.radius = radius;
  }
}


